import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, realpathSync, renameSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { recordedInvocations, writeStub, type Invocation } from "../src/execute";
import { createFixture, sentinelLauncher, type Fixture } from "../src/fixture";
import { cleanupOwnedProcesses } from "../src/process";
import { Defect, Host, Refusal } from "./host";

// Executes the plugins generated by the real `sentinel integrate opencode --guard-approved-specs`
// against the pinned @opencode/plugin package, with a recording `sentinel` stub on PATH.
// Bun.spawn resolves executables against the PATH the process started with, so `bun run test`
// starts the suite with only the stub directory and system directories on PATH.
const STUB_DIR = join(import.meta.dir, ".stub-bin");

const CHECK = ["check", "--format", "json", "--exclude-spec", "--learn-after", "3"];
const checkFor = (...paths: string[]) => [...CHECK, ...paths.flatMap((path) => ["--path", path])];
const MARKER = "[sentinel spec validation]";

let fixture: Fixture;
let work: string;
let logDir: string;
let responses: string;
let otherCheckout: string;
const loaded: (() => Promise<void> | void)[] = [];

beforeAll(async () => {
  if (process.env.PATH !== `${STUB_DIR}:/usr/bin:/bin`) {
    throw new Error("run this suite with `bun run test` so only the recording stub can be spawned");
  }
  fixture = await createFixture({ harness: "opencode", guard: true, sentinel: sentinelLauncher(process.env)! });
  // Project plugins resolve @opencode/plugin through the host; the fixture links the pinned package.
  symlinkSync(join(import.meta.dir, "node_modules"), join(fixture.root, "node_modules"));
  work = mkdtempSync(join(tmpdir(), "sentinel-opencode-"));
  writeStub(STUB_DIR);
  otherCheckout = realpathSync(mkdtempSync(join(tmpdir(), "sentinel-opencode-checkout-")));
});

afterAll(() => {
  fixture?.cleanup();
  rmSync(work, { recursive: true, force: true });
  rmSync(otherCheckout, { recursive: true, force: true });
  cleanupOwnedProcesses();
});

// Spawned processes see the startup environment only, so the stub reads its log and responses
// from its own state directory, which is reset for every test.
const STATE = join(STUB_DIR, ".state");
let sequence = 0;
beforeEach(() => {
  sequence++;
  rmSync(STATE, { recursive: true, force: true });
  logDir = join(STATE, "log");
  responses = join(STATE, "responses");
  mkdirSync(responses, { recursive: true });
});

afterEach(async () => {
  while (loaded.length) await loaded.pop()!();
});

function respond(key: string, exit: number, stdout = "", stderr = "", delaySeconds = 0): void {
  const dir = join(responses, key);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, "exit"), String(exit));
  writeFileSync(join(dir, "stdout"), stdout);
  writeFileSync(join(dir, "stderr"), stderr);
  if (delaySeconds > 0) writeFileSync(join(dir, "delay"), String(delaySeconds));
}

/** Runs `body` while the stub is absent, so spawning `sentinel` fails like a missing install. */
async function withoutSentinel(body: () => Promise<void>): Promise<void> {
  const stub = join(STUB_DIR, "sentinel");
  renameSync(stub, `${stub}.hidden`);
  try {
    await body();
  } finally {
    renameSync(`${stub}.hidden`, stub);
  }
}

const invocations = (): Invocation[] => recordedInvocations(logDir);

async function load(file: string): Promise<any> {
  return (await import(`${fixture.root}/.opencode/plugins/${file}?run=${sequence}-${Math.random()}`)).default;
}

async function setup(file: string, host: Host): Promise<() => Promise<void>> {
  const plugin = await load(file);
  const cleanup = await plugin.setup(host.context());
  let done = false;
  const dispose = async () => {
    if (done) return;
    done = true;
    await cleanup?.();
  };
  loaded.push(dispose);
  return dispose;
}

async function until(condition: () => boolean, timeoutMs = 5_000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (!condition()) {
    if (Date.now() > deadline) throw new Error("condition not reached");
    await Bun.sleep(10);
  }
}

function sessionHost(): Host {
  const host = new Host(fixture.root);
  host.sessions.set("s1", fixture.root);
  return host;
}

describe("generated plugin definitions", () => {
  test("both plugins load against the pinned package and declare their IDs", async () => {
    expect((await load("sentinel-edit-write.js")).id).toBe("sentinel.edit-write");
    expect((await load("sentinel-openspec-guard.js")).id).toBe("sentinel.openspec-guard");
  });

  test("an invalid plugin entrypoint fails instead of being silently skipped", async () => {
    await expect(import("data:text/javascript,export default")).rejects.toThrow();
  });
});

describe("post-edit quality check", () => {
  test("a completed edit runs the check with exact argv and cwd, and success is silent", async () => {
    respond("check", 0, JSON.stringify({ passed: true }));
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "src/A.java" }, result: { content: "Edit applied." } });
    expect(invocations().map((i) => [i.argv, i.cwd, i.stdin])).toEqual([[checkFor("src/A.java"), realpathSync(fixture.root), ""]]);
    expect(content).toEqual([{ type: "text", text: "Edit applied." }]);
  });

  test("a failing check is delivered in the result the model reads without crashing the call", async () => {
    respond("check", 1, JSON.stringify({ passed: false, gates: [{ id: "format", status: "FAILED" }] }));
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const { content } = await host.after({ tool: "write", sessionID: "s1", input: { filePath: "src/A.java" }, result: { content: "Wrote file." } });
    expect(content?.[0]).toEqual({ type: "text", text: "Wrote file." });
    const feedback = content?.slice(1).map((part) => part.text).join("\n") ?? "";
    expect(feedback).toContain("Sentinel quality check failed");
    expect(feedback).toContain('"status":"FAILED"');
  });

  test("learning prompts are delivered on a passing check", async () => {
    respond("check", 0, JSON.stringify({ passed: true, learning: { prompts: [{ instruction: "Run the formatter before editing." }] } }));
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(content?.map((part) => part.text)).toEqual(["ok", "Run the formatter before editing."]);
  });

  test("learning prompts accompany a failing check", async () => {
    respond("check", 1, JSON.stringify({ passed: false, learning: { prompts: [{ instruction: "Keep tests green." }] } }));
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(content?.map((part) => part.text).join("\n")).toContain("Keep tests green.");
  });

  test("an original tool failure is preserved and never triggers a check", async () => {
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const { event } = await host.after({ tool: "edit", sessionID: "s1", input: {}, status: "error", error: { message: "no match" } });
    expect(event.error).toEqual({ message: "no match" });
    expect(invocations()).toEqual([]);
  });

  test("non-edit tools are ignored", async () => {
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    await host.after({ tool: "read", sessionID: "s1", input: { filePath: "a" }, result: { content: "x" } });
    expect(invocations()).toEqual([]);
  });

  test("structured output and metadata are preserved alongside feedback", async () => {
    respond("check", 1, "quality failed");
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const metadata = { diff: "+a" };
    const { event, content } = await host.after({
      tool: "apply_patch",
      sessionID: "s1",
      input: { patchText: "*** Begin Patch" },
      result: { output: { applied: 1 }, metadata },
    });
    expect(event.result.output).toEqual({ applied: 1 });
    expect(event.result.metadata).toEqual(metadata);
    expect(content?.[0]).toEqual({ type: "text", text: '{"applied":1}' });
    expect(content?.slice(1).map((part) => part.text).join("\n")).toContain("quality failed");
  });

  test("a multi-file patch with a move validates each OpenSpec path once", async () => {
    respond("check", 0, "{}");
    respond("spec-validate", 1, "spec findings");
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    const from = join(fixture.root, "openspec/changes/a/specs/x/spec.md");
    const to = join(fixture.root, "openspec/changes/b/specs/x/spec.md");
    const { content } = await host.after({
      tool: "apply_patch",
      sessionID: "s1",
      input: { patchText: "*** Begin Patch" },
      result: { content: "done", metadata: { files: [{ filePath: from, movePath: to }, { filePath: join(fixture.root, "src/A.java") }, { filePath: from }] } },
    });
    expect(invocations().map((i) => i.argv)).toEqual([checkFor(from, to, join(fixture.root, "src/A.java")), ["spec", "validate", "--", from, to]]);
    expect(content?.map((part) => part.text).join("\n")).toContain("spec findings");
  });

  test("the newer patch tool's path argument targets spec validation", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    await host.after({ tool: "patch", sessionID: "s1", input: { path: "openspec/changes/a/tasks.md" }, result: { content: "ok" } });
    expect(invocations().map((i) => i.argv)).toEqual([checkFor("openspec/changes/a/tasks.md"), ["spec", "validate", "--", "openspec/changes/a/tasks.md"]]);
  });

  test("an unavailable Sentinel executable is a bounded diagnostic, not a crashed call", async () => {
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    await withoutSentinel(async () => {
      const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
      expect(content?.map((part) => part.text).join("\n")).toContain("Sentinel could not run");
    });
  });
});

describe("session location", () => {
  test("checks run in the session's current location rather than the plugin location", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    host.sessions.set("s2", otherCheckout);
    await setup("sentinel-edit-write.js", host);
    await host.after({ tool: "edit", sessionID: "s2", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations().map((i) => i.cwd)).toEqual([otherCheckout]);
  });

  test("multiple checkouts and a moved session each use their current location", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    host.sessions.set("s2", otherCheckout);
    await setup("sentinel-edit-write.js", host);
    await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    await host.after({ tool: "edit", sessionID: "s2", input: { filePath: "a" }, result: { content: "ok" } });
    host.sessions.set("s1", otherCheckout);
    await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations().map((i) => i.cwd)).toEqual([realpathSync(fixture.root), otherCheckout, otherCheckout]);
  });

  test("a failed location lookup skips the check instead of guessing a directory", async () => {
    const host = sessionHost();
    host.sessionLookupFails = true;
    await setup("sentinel-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations()).toEqual([]);
    expect(content).toEqual([{ type: "text", text: "ok" }]);
  });
});

describe("idle validation", () => {
  test("idle findings are delivered once per user turn with the documented prompt shape", async () => {
    respond("spec-validate", 1, "Spec findings: missing scenario");
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    host.idle("s1");
    await until(() => host.prompts.length === 1);
    expect(host.prompts[0]).toEqual({
      sessionID: "s1",
      text: `${MARKER}\nSpec findings: missing scenario`,
      metadata: { sentinel: MARKER },
      delivery: "queue",
    });
    expect(invocations().map((i) => [i.argv, i.cwd])).toEqual([[["spec", "validate"], realpathSync(fixture.root)]]);
    // Sentinel's own prompt does not reset eligibility; repeated idles stay silent.
    host.idle("s1");
    await until(() => invocations().length === 2);
    await Bun.sleep(50);
    expect(host.prompts.length).toBe(1);
    // A new external user prompt allows one more hand-off.
    await host.runSessionHook("prompt", { sessionID: "s1", prompt: { text: "please continue" }, delivery: "queue" });
    host.idle("s1");
    await until(() => host.prompts.length === 2);
  });

  test("passing validation and Sentinel failures never prompt the agent", async () => {
    respond("spec-validate", 0, "");
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    host.idle("s1");
    await until(() => invocations().length === 1);
    // Let the first validation finish; an idle event during it is ignored as overlapping.
    await Bun.sleep(200);
    respond("spec-validate", 2, "", "internal error");
    host.idle("s1");
    await until(() => invocations().length === 2);
    await Bun.sleep(50);
    expect(host.prompts).toEqual([]);
  });

  test("overlapping idle events for the same session run one validation", async () => {
    respond("spec-validate", 1, "findings", "", 0.3);
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    host.idle("s1");
    host.idle("s1");
    host.idle("s1");
    await until(() => host.prompts.length === 1);
    await Bun.sleep(400);
    expect(invocations().length).toBe(1);
  });

  test("idle validation uses the session's location from the event", async () => {
    respond("spec-validate", 0, "");
    const host = sessionHost();
    host.sessions.set("s2", otherCheckout);
    await setup("sentinel-edit-write.js", host);
    host.idle("s2");
    await until(() => invocations().length === 1);
    expect(invocations()[0].cwd).toBe(otherCheckout);
  });

  test("a stale validation that finishes after a new user turn is not delivered", async () => {
    respond("spec-validate", 1, "old findings", "", 0.3);
    const host = sessionHost();
    await setup("sentinel-edit-write.js", host);
    host.idle("s1");
    await Bun.sleep(50);
    await host.runSessionHook("prompt", { sessionID: "s1", prompt: { text: "new turn" }, delivery: "queue" });
    await until(() => invocations().length === 1);
    await Bun.sleep(100);
    expect(host.prompts).toEqual([]);
  });

  test("unloading stops the subscription, disposes hooks and drops late results", async () => {
    respond("spec-validate", 1, "findings", "", 0.3);
    const host = sessionHost();
    const dispose = await setup("sentinel-edit-write.js", host);
    host.idle("s1");
    await Bun.sleep(50);
    await dispose();
    expect(host.toolHooks.get("execute.after")).toEqual([]);
    expect(host.sessionHooks.get("prompt")).toEqual([]);
    host.idle("s1");
    await Bun.sleep(500);
    expect(host.prompts).toEqual([]);
  });

  test("reloading leaves exactly one active observer", async () => {
    respond("spec-validate", 1, "findings");
    const host = sessionHost();
    const first = await setup("sentinel-edit-write.js", host);
    await first();
    await setup("sentinel-edit-write.js", host);
    expect(host.toolHooks.get("execute.after")?.length).toBe(1);
    host.idle("s1");
    await until(() => host.prompts.length === 1);
    await Bun.sleep(100);
    expect(invocations().length).toBe(1);
  });
});

describe("approved-artifact guard", () => {
  const guard = async () => {
    const host = sessionHost();
    await setup("sentinel-openspec-guard.js", host);
    return host;
  };

  test("a protected edit is refused with Sentinel's reason", async () => {
    respond("spec-guard", 1, "Refused: openspec/specs is approved.");
    const host = await guard();
    await expect(host.before({ tool: "edit", sessionID: "s1", input: { filePath: "openspec/specs/a/spec.md" } })).rejects.toThrow(
      new Refusal("Refused: openspec/specs is approved."),
    );
    expect(invocations().map((i) => [i.argv, i.cwd])).toEqual([[["spec", "guard", "--", "openspec/specs/a/spec.md"], realpathSync(fixture.root)]]);
  });

  test("an active-change edit is allowed", async () => {
    respond("spec-guard", 0);
    const host = await guard();
    await host.before({ tool: "write", sessionID: "s1", input: { filePath: "openspec/changes/a/tasks.md" } });
    expect(invocations().length).toBe(1);
  });

  test("patches and shell commands pass their payload on stdin", async () => {
    respond("spec-guard", 0);
    const host = await guard();
    await host.before({ tool: "apply_patch", sessionID: "s1", input: { patchText: "*** Begin Patch\n" } });
    await host.before({ tool: "bash", sessionID: "s1", input: { command: "rm -rf openspec/specs", workdir: "sub/dir" } });
    await host.before({ tool: "skill", sessionID: "s1", input: { name: "openspec-archive-change" } });
    expect(invocations().map((i) => [i.argv, i.stdin])).toEqual([
      [["spec", "guard", "--patch-stdin"], "*** Begin Patch\n"],
      [["spec", "guard", "--shell-stdin", "--cwd", join(fixture.root, "sub/dir")], "rm -rf openspec/specs"],
      [["spec", "guard", "--skill", "openspec-archive-change"], ""],
    ]);
  });

  test("a shell command without a workdir uses the session location", async () => {
    respond("spec-guard", 0);
    const host = await guard();
    await host.before({ tool: "bash", sessionID: "s1", input: { command: "ls" } });
    expect(invocations()[0].argv).toEqual(["spec", "guard", "--shell-stdin", "--cwd", fixture.root]);
  });

  test("malformed relevant input is sent as uninspectable", async () => {
    respond("spec-guard", 1, "Refused: input could not be inspected.");
    const host = await guard();
    await expect(host.before({ tool: "edit", sessionID: "s1", input: {} })).rejects.toThrow(Refusal);
    expect(invocations()[0].argv).toEqual(["spec", "guard", "--unreadable-input"]);
  });

  test("Sentinel exit 2 or an unavailable executable lets the call proceed", async () => {
    respond("spec-guard", 2, "", "internal");
    const host = await guard();
    await host.before({ tool: "edit", sessionID: "s1", input: { filePath: "openspec/specs/a/spec.md" } });
    await withoutSentinel(() => host.before({ tool: "edit", sessionID: "s1", input: { filePath: "openspec/specs/a/spec.md" } }));
  });

  test("a failed location lookup lets the call proceed with a diagnostic", async () => {
    const host = await guard();
    host.sessionLookupFails = true;
    await host.before({ tool: "edit", sessionID: "s1", input: { filePath: "openspec/specs/a/spec.md" } });
    expect(invocations()).toEqual([]);
  });

  test("other tools are not inspected and unload disposes the hook", async () => {
    const host = sessionHost();
    const dispose = await setup("sentinel-openspec-guard.js", host);
    await host.before({ tool: "read", sessionID: "s1", input: { filePath: "openspec/specs/a/spec.md" } });
    expect(invocations()).toEqual([]);
    await dispose();
    expect(host.toolHooks.get("execute.before")).toEqual([]);
  });
});

test("the host emulation treats an execute.after rejection as a defect", async () => {
  const host = new Host("/tmp");
  host.toolHooks.set("execute.after", [() => Promise.reject(new Error("boom"))]);
  await expect(host.after({ tool: "edit", sessionID: "s1", input: {}, result: { content: "x" } })).rejects.toThrow(Defect);
});
